def inner_product_contraint_poly(accip_x,b_x,s_x):

    #shifted accip
    accip_omega_x=list(accip_x)
    accip_omega_x=accip_omega_x[4:]+accip_omega_x[:4]
    # print("shifted:",accip_omega_x)

    #Compute constraint polynomial
    constraint = vect_sub(vect_sub(accip_omega_x ,accip_x,S_PRIME) ,
                               vect_mul(b_x,s_x,S_PRIME ),S_PRIME)


    # factor= [-D[-4],1] # (x- D[-4])
    c1_x= vect_mul( constraint, Not_last,S_PRIME)

    return c1_x

