def conditional_additon_constraint_poly(acc_x,acc_y,b_x,p_x,p_y):

    one_m_bx=vect_sub(1, b_x, S_PRIME)
    accx_wx=list(acc_x)
    accx_wx = accx_wx[4:] + accx_wx[:4]
    # print("accx_wx:", accx_wx)
    accy_wx=list(acc_y)
    accy_wx = accy_wx[4:] + accy_wx[:4]
    # print("accy_wx:", accy_wx)
    accx_m_px=vect_sub(acc_x,p_x,S_PRIME)
    accx_m_px_square=vect_mul(accx_m_px,accx_m_px,S_PRIME)
    py_x_m_accy_x=vect_sub(p_y,acc_y,S_PRIME)
    accx_wx_m_accx_x=vect_sub(accx_wx,acc_x,S_PRIME)
    factor= Not_last

    # (accx - px)^2 * (accx + px + accx(ωx))
    term1 = vect_mul(accx_m_px_square,
                     vect_add(vect_add(acc_x, p_x, S_PRIME), accx_wx, S_PRIME),
                     S_PRIME)
    # (py - accy)^2
    term2 = vect_mul(py_x_m_accy_x,
                     py_x_m_accy_x,
                     S_PRIME)
    c2_x = vect_add(
        vect_mul(b_x, vect_sub(term1, term2, S_PRIME), S_PRIME),
        vect_mul(vect_sub(1, b_x, S_PRIME), vect_sub(accy_wx, acc_y, S_PRIME), S_PRIME),
        S_PRIME
    )

    c2x=vect_mul(c2_x,factor,S_PRIME)

    c3_x= vect_add(
        vect_mul(b_x,vect_sub(vect_mul(accx_m_px, vect_add(accy_wx,acc_y,S_PRIME),S_PRIME),
                              vect_mul(py_x_m_accy_x,accx_wx_m_accx_x,S_PRIME),S_PRIME),S_PRIME),
           vect_mul(one_m_bx, accx_wx_m_accx_x,S_PRIME),S_PRIME
           )

    c3x= vect_mul(c3_x,factor,S_PRIME)
    return c2x,c3x

