def booleanity_constraint_poly(b_x):

    """
    input: bits vector
    output: booleanity constraint
    """
    one_m_bx=vect_sub( 1,b_x, S_PRIME)
    # print("poly_sub:", one_m_bx)
    # print("bx:", b_x)
    c4x= vect_mul(b_x, one_m_bx, S_PRIME)
    # print("rsult:",c4x)
    return c4x

