def conditional_additon_boundary_poly(acc_x,acc_y,S_P, ResultPoint, Result_plus_Seed):

    seed_x,seed_y= S_P
    # print("seed x,y;",seed_x,seed_y)
    # r_x,r_y=ResultPoint
    # print("result",ResultPoint)
    rx_p_sx,ry_p_sy=Result_plus_Seed

    # c5_x=(acc_x -sx) * L_0_x +(acc_x-rx-sx) * L_x_m_4
    c5_x=vect_add( vect_mul
                   (vect_sub
                    (acc_x , seed_x, S_PRIME), L_0_x_4x,S_PRIME),
                   vect_mul(
                       vect_sub
                                 (acc_x, rx_p_sx,S_PRIME),L_N_4_x_4x, S_PRIME), S_PRIME)

    # c6_x=(acc_y -sy)*L_0_x + (acc_y-ry-sy) * L_x_m_4
    c6_x= vect_add(vect_mul
                   (vect_sub
                    (acc_y,seed_y,S_PRIME),L_0_x_4x,S_PRIME),
                   vect_mul(
                       vect_sub(acc_y,ry_p_sy,S_PRIME),L_N_4_x_4x,S_PRIME),S_PRIME)
    return c5_x, c6_x


