#constraint 7
def inner_product_boundary_constraint_poly(acc_ip):

    # c7_x=acc_ip *L_0_x + (acc_ip-1)* L_x_m_4
    c7_x=vect_add(vect_mul(acc_ip, L_0_x_4x, S_PRIME),
                  vect_mul(vect_sub(acc_ip,1,S_PRIME),
                                L_N_4_x_4x,S_PRIME),S_PRIME)

    return c7_x


